CREATE TABLE public.master_admin_reservation (id boolean PRIMARY KEY DEFAULT true CHECK(id), email text UNIQUE NOT NULL DEFAULT 'swiftdeliveryexpress4@gmail.com'); GRANT SELECT,INSERT ON public.master_admin_reservation TO service_role; ALTER TABLE public.master_admin_reservation ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.assign_verified_master() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND lower(NEW.email)='swiftdeliveryexpress4@gmail.com' AND NOT EXISTS(SELECT 1 FROM public.user_roles) THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'master_admin') ON CONFLICT(role) DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_verified_master AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_verified_master();